          "const aircraftModel = get('Aircraft Model') || get('Model') || get('aircraft_model');\n"
          "const aircraftDamage = get('Aircraft Damage') || get('Damage') || get('aircraft_damage');\n"
          "console && console.log ? null : null;\n"
          "return { ntsbNumber: ntsbNumber, eventDate: eventDate, location: location, "
